  async function localFileAction(mode,id,value){const db=await mediaDb();return new Promise((resolve,reject)=>{const tx=db.transaction('files',mode==='get'?'readonly':'readwrite'),store=tx.objectStore('files'),req=mode==='get'?store.get(id):mode==='delete'?store.delete(id):store.put(value,id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
