  const worldDefaults={a:'#a56e79',b:'#686a9c'};
  function worldColors(timeline){const faction=factions.find(f=>f.id===timeline?.factionId)||factions.find(f=>f.name===timeline?.worldName);const theme=faction?.themeColor;return {a:safeColor(theme?.primary||timeline?.worldColorA||worldDefaults.a),b:safeColor(theme?.secondary||timeline?.worldColorB||worldDefaults.b)};}
  function splitWorldNames(value){return [...new Set(String(value||'').split(/[,，、\n]+/).map(name=>name.trim()).filter(Boolean))];}
  function eventSourceTimeline(event,fallback){return timelines.find(item=>item.id===(event?._sourceTimelineId||fallback?.id))||fallback;}
  function eventWorldName(event,timeline){const source=eventSourceTimeline(event,timeline);return String(event?.worldName||factions.find(f=>f.id===event?.worldFactionId)?.name||source?.worldName||factions.find(f=>f.id===source?.factionId)?.name||'未標記世界觀').trim();}
  const timelineLinkId=link=>link.id||`timeline_${link.timelineId}`;
