  const linkedEventKey=(timelineId,eventId)=>`${timelineId}::${eventId}`;
  function timelineMainOrder(timeline){const own=byOrder(timeline?.events||[]),links=(timeline?.linkedTimelines||[]).filter(link=>timelines.some(item=>item.id===link.timelineId&&item.id!==timeline.id)),eventById=new Map(own.map(event=>[event.id,event])),linkById=new Map(links.filter(link=>link.mode==='all').map(link=>[timelineLinkId(link),link])),linkedEvents=new Map();for(const link of links.filter(row=>row.mode==='events')){const source=timelines.find(item=>item.id===link.timelineId);for(const event of byOrder(source?.events||[]))if((link.eventIds||[]).includes(event.id))linkedEvents.set(linkedEventKey(source.id,event.id),{timelineId:source.id,eventId:event.id});}const seenEvents=new Set(),seenLinks=new Set(),seenLinkedEvents=new Set(),result=[];for(const item of Array.isArray(timeline?.mainTimelineOrder)?timeline.mainTimelineOrder:[]){if(item?.kind==='event'&&eventById.has(item.id)&&!seenEvents.has(item.id)){result.push({kind:'event',id:item.id});seenEvents.add(item.id);}else if(item?.kind==='timeline'&&linkById.has(item.id)&&!seenLinks.has(item.id)){result.push({kind:'timeline',id:item.id});seenLinks.add(item.id);}else if(item?.kind==='linkedEvent'){const key=linkedEventKey(item.timelineId,item.eventId);if(linkedEvents.has(key)&&!seenLinkedEvents.has(key)){result.push({kind:'linkedEvent',timelineId:item.timelineId,eventId:item.eventId});seenLinkedEvents.add(key);}}}for(const event of own)if(!seenEvents.has(event.id)){result.push({kind:'event',id:event.id});seenEvents.add(event.id);}for(const link of links){if(link.mode==='all'){const id=timelineLinkId(link);if(!seenLinks.has(id)){result.push({kind:'timeline',id});seenLinks.add(id);}}else{const source=timelines.find(item=>item.id===link.timelineId);for(const event of byOrder(source?.events||[]))if((link.eventIds||[]).includes(event.id)){const key=linkedEventKey(source.id,event.id);if(!seenLinkedEvents.has(key)){result.push({kind:'linkedEvent',timelineId:source.id,eventId:event.id});seenLinkedEvents.add(key);}}}}return result;}
  function linkedTimelineEntries(timeline,included=new Set()){if(!timeline?.isMainTimeline)return [];const result=[],seen=new Set();for(const link of timeline.linkedTimelines||[]){if(link.mode!=='events')continue;const source=timelines.find(item=>item.id===link.timelineId);if(!source||source.id===timeline.id)continue;const selected=byOrder(source.events||[]).filter(event=>(link.eventIds||[]).includes(event.id));for(const event of selected){const key=linkedEventKey(source.id,event.id);if(seen.has(key)||included.has(key))continue;seen.add(key);result.push({...event,_sourceTimelineId:source.id,_sourceTimelineName:source.name,_linkedFromMain:true});}}return result;}
