  function groupTimelineEvents(events){const groups=[];for(const event of events){const explicit=String(event.simultaneousGroup||'').trim(),when=String(event.when||'').trim(),key=explicit?`group:${explicit.toLocaleLowerCase()}`:when?`when:${when.toLocaleLowerCase()}`:`event:${event._sourceTimelineId||''}:${event.id}`,previous=groups[groups.length-1];if(previous?.key===key)previous.events.push(event);else groups.push({key,label:explicit||when,events:[event]});}return groups;}
