    const groups=groupTimelineEvents(events);
    const filters=`<div class="timeline-world-filters" role="group" aria-label="依世界觀篩選"><span>世界觀</span><button type="button" data-world="" class="${selectedTimelineWorld?'':'is-active'}" onclick="OCFeatures.filterTimelineWorld(this.dataset.world)">全部</button>${worldNames.map(name=>`<button type="button" data-world="${esc(name)}" class="${selectedTimelineWorld.toLocaleLowerCase()===name.toLocaleLowerCase()?'is-active':''}" onclick="OCFeatures.filterTimelineWorld(this.dataset.world)">${esc(name)}</button>`).join('')}</div>`;
    const renderEvent=(event,groupIndex)=>{const a=safeColor(event.colorA),b=safeColor(event.colorB),people=peopleFor(event),worldLabel=eventWorldName(event,timeline),sourceId=event._sourceTimelineId||timeline.id,sourceName=event._sourceTimelineName||timeline.name,orderIndex=allEvents.findIndex(row=>row.id===event.id&&row._sourceTimelineId===sourceId),linked=!!event._linkedFromMain,mainKey=event._mainOrderKey||'',sourceBadge=linked?`<span class="timeline-source-badge"><i class="fa-solid fa-link"></i> 來自 ${esc(sourceName)}</span>`:'';if(event._timelineLinkBlock){const linkId=event._timelineLinkId,up=mainKey?`<button type="button" aria-label="入口上移" onclick="event.stopPropagation();OCFeatures.shiftMainTimelineItem('${esc(mainKey)}',-1)">↑</button><button type="button" aria-label="入口下移" onclick="event.stopPropagation();OCFeatures.shiftMainTimelineItem('${esc(mainKey)}',1)">↓</button>`:'';return `<article class="timeline-node timeline-link-block" draggable="true" tabindex="0" role="button" data-main-order-key="${esc(mainKey)}" data-event-id="${esc(event.id)}" data-source-timeline-id="${esc(sourceId)}" style="--event-a:${a};--event-b:${b}" onclick="OCFeatures.openLinkedTimeline('${esc(event._linkedTimelineId)}')" onkeydown="if(event.target===this&&(event.key==='Enter'||event.key===' ')){event.preventDefault();OCFeatures.openLinkedTimeline('${esc(event._linkedTimelineId)}')}"><div class="timeline-node-card"><div class="timeline-node-top"><small><i class="fa-solid fa-layer-group"></i> 整條時間線</small><span class="timeline-node-actions">${up}<span class="timeline-drag" title="拖曳至主線任意位置">⋮⋮</span></span></div><span class="timeline-event-world"><i class="fa-solid fa-globe"></i> ${esc(worldLabel)} · ${esc(sourceName)}</span><h3>${esc(event.title)}</h3>${event.summary?`<p class="timeline-link-note">${esc(event.summary)}</p>`:''}<div class="timeline-node-bottom"><span class="timeline-link-open-label"><i class="fa-solid fa-arrow-right-to-bracket"></i> 開啟這條時間線</span><button type="button" class="timeline-edit-button" onclick="event.stopPropagation();OCFeatures.openTimelineLinks('${esc(event._linkedTimelineId)}')"><i class="fa-solid fa-pen"></i> 編輯入口</button></div><small class="timeline-open">點擊進入 · 返回時保留主線位置 ↗</small></div></article>`;}const actions=mainKey?`<button type="button" aria-label="上移" onclick="event.stopPropagation();OCFeatures.shiftMainTimelineItem('${esc(mainKey)}',-1)">↑</button><button type="button" aria-label="下移" onclick="event.stopPropagation();OCFeatures.shiftMainTimelineItem('${esc(mainKey)}',1)">↓</button><span class="timeline-drag" title="拖曳排列">⋮⋮</span>`:linked?sourceBadge:`<button type="button" aria-label="事件上移" onclick="event.stopPropagation();OCFeatures.shiftEvent('${esc(event.id)}',-1,'${esc(sourceId)}')">↑</button><button type="button" aria-label="事件下移" onclick="event.stopPropagation();OCFeatures.shiftEvent('${esc(event.id)}',1,'${esc(sourceId)}')">↓</button><span class="timeline-drag" title="拖曳排列">⋮⋮</span>`;return `<article class="timeline-node${linked?' is-linked-event':''}" ${mainKey||!linked?'draggable="true"':''} tabindex="0" role="button" data-main-order-key="${esc(mainKey)}" data-event-id="${esc(event.id)}" data-source-timeline-id="${esc(sourceId)}" style="--event-a:${a};--event-b:${b}" onclick="OCFeatures.openEventDetail('${esc(event.id)}','${esc(sourceId)}')" onkeydown="if(event.target===this&&(event.key==='Enter'||event.key===' ')){event.preventDefault();OCFeatures.openEventDetail('${esc(event.id)}','${esc(sourceId)}')}"><div class="timeline-node-card"><div class="timeline-node-top"><small>${esc(event.when||`事件 ${orderIndex+1}`)}</small><span class="timeline-node-actions">${actions}</span></div><span class="timeline-event-world"><i class="fa-solid fa-globe"></i> ${esc(worldLabel)}</span>${linked?sourceBadge:''}<h3>${esc(event.title)}</h3>${event.summary?`<p>${esc(event.summary)}</p>`:''}<div class="timeline-node-bottom">${people.length?avatarStack(people):'<span class="timeline-no-people">尚未關聯人物</span>'}<button type="button" class="timeline-edit-button" onclick="event.stopPropagation();OCFeatures.openEvent('${esc(event.id)}',null,'${esc(sourceId)}')"><i class="fa-solid fa-pen"></i> ${linked?'編輯來源':'編輯'}</button></div><small class="timeline-open">${linked?'開啟來源事件 ↗':'閱讀事件始末 ↗'}</small></div></article>`;};
    const returnBanner=timelineReturnContext?.linkedTimelineId===timeline.id?`<div class="timeline-return-banner"><span><i class="fa-solid fa-arrow-turn-up"></i> 從主時間線前來 · 返回時會恢復原本位置</span><button type="button" onclick="OCFeatures.returnToMainTimeline()"><i class="fa-solid fa-arrow-left"></i> 返回主時間線</button></div>`:'';
    canvas.innerHTML=`${returnBanner}<div class="timeline-cover" style="--world-a:${colors.a};--world-b:${colors.b}"><small>STORY CHRONICLE · ${esc(world)}</small><h2>${timeline.isMainTimeline?'<span class="timeline-main-badge"><i class="fa-solid fa-star"></i> 主時間線</span> ':''}${esc(timeline.name)}</h2><p>${esc(timeline.description||'把不同世界觀的事件收進同一條主線；相同時間或群組會並列呈現。')}</p><span>${events.length} 個事件</span>${filters}</div><div class="timeline-rail" style="--world-a:${colors.a};--world-b:${colors.b}">${groups.length?groups.map((group,groupIndex)=>{const first=group.events[0],beforeIndex=Math.max(0,allEvents.findIndex(item=>item.id===first.id&&item._sourceTimelineId===first._sourceTimelineId));const label=group.events.length>1?`同時發生${group.label?` · ${group.label}`:''}`:group.label?`時間節點 · ${group.label}`:`事件節點 ${groupIndex+1}`;return `<div class="timeline-gap"><button onclick="OCFeatures.openEvent(null,${beforeIndex},'${esc(timeline.id)}')" title="在此處新增事件">＋</button></div><section class="timeline-moment${group.events.length>1?' is-simultaneous':''}" aria-label="${esc(label)}"><div class="timeline-moment-heading"><span class="timeline-moment-dot"></span><span>${esc(label)}</span>${group.events.length>1?`<small>${group.events.length} 件</small>`:''}</div><div class="timeline-moment-grid">${group.events.map(event=>renderEvent(event,groupIndex)).join('')}</div></section>`;}).join(''):`<div class="timeline-empty-filter"><i class="fa-regular fa-compass"></i><strong>這個篩選下還沒有事件</strong><span>新增事件時選擇世界觀，或切回「全部」查看。</span></div>`}<div class="timeline-gap"><button onclick="OCFeatures.openEvent(null,${(timeline.events||[]).length},'${esc(timeline.id)}')" title="在結尾新增事件">＋</button></div></div>`;
