  function selectTimeline(id){if(timelineReturnContext&&id!==timelineReturnContext.linkedTimelineId)timelineReturnContext=null;selectedTimelineId=id;selectedTimelineWorld='';localStorage.setItem('oc_selected_timeline',id);renderTimeline();}
  function openLinkedTimeline(id){const target=timelines.find(item=>item.id===id);if(!target)return;timelineReturnContext={mainTimelineId:selectedTimelineId,linkedTimelineId:id,world:selectedTimelineWorld,scrollY:window.scrollY,search:$('timelineCharSearch')?.value||'',characterId:$('timelineCharFilter')?.value||''};selectedTimelineId=id;selectedTimelineWorld='';$('timelineCharSearch').value='';$('timelineCharFilter').value='';localStorage.setItem('oc_selected_timeline',id);renderTimeline();requestAnimationFrame(()=>document.getElementById('timelineCanvas')?.scrollIntoView({behavior:'smooth',block:'start'}));}
