  function persistMainTimelineOrder(timeline,items){timeline.mainTimelineOrder=items.map(item=>({...item}));items.forEach((item,index)=>{if(item.kind==='event'){const event=timeline.events?.find(row=>row.id===item.id);if(event)event.order=index+1;}else if(item.kind==='timeline'){const link=(timeline.linkedTimelines||[]).find(row=>timelineLinkId(row)===item.id);if(link)link.order=index+1;}});}
