  function openEventDetail(id,sourceTimelineId=selectedTimelineId){const timeline=timelines.find(t=>t.id===sourceTimelineId),event=timeline?.events?.find(item=>item.id===id);if(!event)return;const people=peopleFor(event);$('timelineReadHero').style.setProperty('--world-a',safeColor(event.colorA||'#bf806d'));$('timelineReadHero').style.setProperty('--world-b',safeColor(event.colorB||'#6f629b'));$('timelineReadWorld').textContent=`${eventWorldName(event,timeline)} · ${timeline.name}`;$('timelineReadWhen').textContent=event.when||(event.simultaneousGroup?`同時發生 · ${event.simultaneousGroup}`:'時間未標記');$('timelineReadTitle').textContent=event.title;$('timelineReadPeople').innerHTML=people.map(c=>`<span class="timeline-read-person"><img src="${esc(c.avatar||'')}" alt="" onerror="this.style.display='none'"><span>${esc(c.name)}</span></span>`).join('');$('timelineReadSummary').textContent=event.summary||'';$('timelineReadSummary').hidden=!event.summary;$('timelineReadStory').textContent=event.story||'尚未填寫事件始末。';$('timelineReadSections').innerHTML=(event.sections||[]).map(section=>`<section class="timeline-read-section"><h3>${esc(section.title||'補充')}</h3><div class="timeline-read-text">${esc(section.content||'')}</div></section>`).join('');$('timelineReadEditBtn').onclick=()=>{closeEventDetail();openEvent(id,null,sourceTimelineId);};$('timelineReadModal').classList.add('active');}
