  function exportTimelineHtml(){const t=timelines.find(t=>t.id===selectedTimelineId);if(!t)return;const world=worldColors(t);const cards=groupTimelineEvents(timelineEventsForDisplay(t)).map(group=>`<section style="margin:28px 0;padding:18px;border:1px solid #ffffff28;border-radius:20px;background:#ffffff08"><h2 style="font-size:1rem;color:#e9cbaa">${esc(group.events.length>1?'同時發生':'時間節點')}${group.label?` · ${esc(group.label)}`:''}</h2><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px">${group.events.map(e=>`<article style="border-left:6px solid ${safeColor(e.colorA)};padding:18px 24px;background:linear-gradient(105deg,${safeColor(e.colorA)}22,${safeColor(e.colorB)}22);border-radius:16px"><small>${esc(eventWorldName(e,t))} · ${esc(e._sourceTimelineName||t.name)}${e.when?` · ${esc(e.when)}`:''}</small><h3>${esc(e.title)}</h3><p>${esc(e.summary)}</p><p>人物：${(e.charIds||[]).map(id=>esc(characters.find(c=>c.id===id)?.name)).filter(Boolean).join('、')}</p>${e.story?`<h3>事件始末</h3><p style="white-space:pre-wrap">${esc(e.story)}</p>`:''}${(e.sections||[]).map(s=>`<h3>${esc(s.title)}</h3><p style="white-space:pre-wrap">${esc(s.content)}</p>`).join('')}</article>`).join('')}</div></section>`).join('');download(`${t.name}-視覺時間線.html`,`<!doctype html><html lang="zh-TW"><meta charset="utf-8"><title>${esc(t.name)}</title><style>body{max-width:1000px;margin:48px auto;padding:0 24px;background:#17151d;color:#f4ede6;font:16px/1.75 system-ui}h1{font-size:42px;background:linear-gradient(110deg,${world.a},${world.b});padding:18px 24px;border-radius:16px}@media print{body{background:white;color:#222}}</style><h1>${esc(t.name)}</h1><p>涵蓋世界觀：${esc(timelineWorldNames(t).join('、')||'未設定')}</p><p>${esc(t.description)}</p>${cards}</html>`,'text/html;charset=utf-8');}
  function filterChoices(inputId,listId){const query=($(inputId)?.value||'').trim().toLocaleLowerCase(),list=$(listId);if(!list)return;list.querySelectorAll('label').forEach(label=>{label.hidden=!!query&&!label.textContent.toLocaleLowerCase().includes(query);});}

