  function draftDb(){if(!draftDbPromise)draftDbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('oc-editor-drafts',1);request.onupgradeneeded=()=>request.result.createObjectStore('drafts');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});return draftDbPromise;}
