  function renderGallery(){updateMediaFileSelection();const items=imagesForChar(galleryCharId),toolbar=`<div class="media-order-toolbar ${galleryReorderMode?'is-editing':''}"><div><strong>${galleryReorderMode?'排列圖廊順序':'圖片排列'}</strong><small>${galleryReorderMode?'用箭頭微調，順序會同步套用到人設卡圖廊。':'可自訂這位人物的圖片展示順序。'}</small></div><button type="button" class="btn btn-xs ${galleryReorderMode?'btn-primary':'btn-outline'}" onclick="OCFeatures.toggleGalleryReorder()"><i class="fa-solid ${galleryReorderMode?'fa-check':'fa-arrow-down-1-9'}"></i> ${galleryReorderMode?'完成排序':'調整順序'}</button></div>`;let orderToolbar=$('mediaOrderToolbar');if(!orderToolbar){orderToolbar=document.createElement('div');orderToolbar.id='mediaOrderToolbar';$('mediaMasonry').before(orderToolbar);}orderToolbar.innerHTML=toolbar;$('mediaMasonry').innerHTML=items.length?items.map((item,index)=>`<div class="media-tile ${galleryReorderMode?'is-reordering':''}" data-image-order="${index}"><img data-media-id="${esc(item.id)}" alt="${esc(item.caption||'人物圖片')}"><div class="media-tile-caption"><span>${esc(item.caption||'未命名圖片')}</span><button class="btn btn-xs btn-outline" onclick="OCFeatures.editImage('${esc(item.id)}')">編輯</button></div>${galleryReorderMode?`<div class="media-order-controls"><span><i class="fa-solid fa-grip-lines-vertical"></i> 第 ${index+1} 張</span><div><button type="button" ${index===0?'disabled':''} onclick="OCFeatures.shiftGalleryImage('${esc(item.id)}',-1)" aria-label="圖片上移" title="向前移動">↑</button><button type="button" ${index===items.length-1?'disabled':''} onclick="OCFeatures.shiftGalleryImage('${esc(item.id)}',1)" aria-label="圖片下移" title="向後移動">↓</button></div></div>`:''}</div>`).join(''):'<div class="empty-state">尚無圖片。選擇圖片後會先存入本機並立即預覽。</div>';items.forEach(async item=>{const img=$('mediaMasonry').querySelector(`img[data-media-id="${CSS.escape(item.id)}"]`);try{const url=await mediaSource(item);if(img?.isConnected)img.src=url;}catch(error){if(img?.isConnected)img.alt=error.message;}});}
  async function uploadImages(){const input=$('mediaUploadInput'),files=[...input.files],status=$('mediaUploadStatus');if(!files.length)return;try{for(const file of files){if(!/^image\/(png|jpeg|webp|gif|avif)$/i.test(file.type))throw new Error(`${file.name} 格式不支援，請使用 PNG、JPEG、WebP、GIF 或 AVIF。`);if(file.size>20*1024*1024)throw new Error(`${file.name} 超過 20 MB。`);}for(let i=0;i<files.length;i++){const file=files[i],key=uid('image');status.textContent=`儲存到本機 ${i+1}/${files.length}：${file.name}`;await localFileAction('put',key,file);mediaLibrary.push({id:key,caption:file.name,charIds:[galleryCharId],type:file.type,size:file.size,createdAt:Date.now(),localOnly:true});}save();input.value='';status.textContent=`已加入本機圖庫 ${files.length} 張，可立即預覽；備份人設卡時可批次同步 R2。`;renderGallery();renderCharacterCards();renderCpModule();}catch(error){status.textContent=error.name==='QuotaExceededError'?'本機儲存空間不足，請改用較小圖片或稍後清理瀏覽器資料。':error.message;}}
